-- Base de conhecimento ESG: 40 registros iniciais. Proposta metodológica, não
-- certificação nem validação legal; passa por revisão editorial antes de uso em produção.
--
-- Prévia (dry-run): rode com "rollback;" no lugar do "commit;" do fim do arquivo.
-- Idempotente: rodar de novo não duplica nem sobrescreve registros já existentes,
-- inclusive os editados. Para desfazer: supabase/scripts/rollback_knowledge_seed.sql.
--
-- Categorias do banco (mapeamento explícito; o tema original fica em thematic_category):
--   Fundamentos ESG -> concept | Ambiental, Social e Governança -> evaluation_criteria
--   Avaliação e triagem -> classification_rule | Indicadores e evidências -> recommendation
begin;

alter table public.esg_knowledge_items
  add column if not exists slug text unique,
  add column if not exists thematic_category text,
  add column if not exists origin text,
  add column if not exists reviewed_at timestamptz;

with seed (slug, title, description, category, thematic_category, source) as (
  values
  ('esg-01-o-que-e-esg', 'O que é ESG', 'ESG reúne temas ambientais, sociais e de governança. Classifique propostas pelo mecanismo de impacto demonstrado, não apenas pelas palavras utilizadas. Uma iniciativa pode afetar vários pilares.', 'concept', 'Fundamentos ESG', 'Referência metodológica interna proposta — Copiloto ESG v1.0 (não é norma externa).'),
  ('esg-02-impacto-direto-e-indireto', 'Impacto direto e indireto', 'Direto: efeito decorrente da operação ou ação proposta; indireto: efeito em fornecedores, usuários, comunidades ou cadeia de valor. Solicite a relação causal e os limites da análise.', 'concept', 'Fundamentos ESG', 'Referência metodológica interna proposta — Copiloto ESG v1.0 (não é norma externa).'),
  ('esg-03-materialidade-e-relevancia', 'Materialidade e relevância', 'Avalie se o tema é relevante para a atividade, partes interessadas e riscos/impactos da empresa. Materialidade depende do contexto; não atribua relevância universal a um termo isolado.', 'concept', 'Fundamentos ESG', 'Referência metodológica interna proposta — Copiloto ESG v1.0 (não é norma externa).'),
  ('esg-04-linha-de-base-e-adicionalidade', 'Linha de base e adicionalidade', 'Linha de base é o cenário anterior ou de referência; adicionalidade descreve a melhoria atribuível à proposta. Não confunda atividade executada com benefício comprovado.', 'concept', 'Fundamentos ESG', 'Referência metodológica interna proposta — Copiloto ESG v1.0 (não é norma externa).'),
  ('esg-05-horizonte-e-abrangencia-do-impacto', 'Horizonte e abrangência do impacto', 'Registre curto, médio ou longo prazo; local, unidade, empresa ou cadeia de valor; beneficiários, possíveis efeitos adversos e dependências.', 'concept', 'Fundamentos ESG', 'Referência metodológica interna proposta — Copiloto ESG v1.0 (não é norma externa).'),
  ('esg-06-multiclassificacao-esg', 'Multiclassificação ESG', 'Permita pilar principal e secundários. Escolha o principal pelo impacto predominante, justifique os demais e evite somar o mesmo benefício duas vezes.', 'concept', 'Fundamentos ESG', 'Referência metodológica interna proposta — Copiloto ESG v1.0 (não é norma externa).'),
  ('esg-07-eficiencia-energetica', 'Eficiência energética', 'Reconheça redução de kWh por unidade produzida, automação, manutenção, iluminação e otimização operacional. Peça consumo de referência, período, produção e medição pós-implantação. Indicadores possíveis: kWh; kWh/unidade; economia %.', 'evaluation_criteria', 'Ambiental (E)', 'GRI Standards — referência temática geral; verificar norma temática e edição aplicável antes de declarar alinhamento.'),
  ('esg-08-energia-renovavel', 'Energia renovável', 'Identifique geração ou contratação de energia renovável e sua contribuição específica. Diferencie potência instalada (kW) de energia gerada (kWh). Indicadores possíveis: kWh gerados; participação renovável %.', 'evaluation_criteria', 'Ambiental (E)', 'GRI Standards — referência temática geral; verificar norma temática e edição aplicável antes de declarar alinhamento.'),
  ('esg-09-gestao-de-agua', 'Gestão de água', 'Avalie redução de captação, perdas, reúso e eficiência hídrica. Peça volume inicial, finalidade da água, qualidade exigida e método de medição. Indicadores possíveis: m³ captados; m³ reutilizados.', 'evaluation_criteria', 'Ambiental (E)', 'GRI Standards — referência temática geral; verificar norma temática e edição aplicável antes de declarar alinhamento.'),
  ('esg-10-efluentes-e-qualidade-da-agua', 'Efluentes e qualidade da água', 'Reconheça tratamento, monitoramento e redução de cargas poluentes. Solicite parâmetros de qualidade pertinentes e evidências de atendimento às exigências aplicáveis. Indicadores possíveis: m³ tratados; parâmetros de qualidade.', 'evaluation_criteria', 'Ambiental (E)', 'GRI Standards — referência temática geral; verificar norma temática e edição aplicável antes de declarar alinhamento.'),
  ('esg-11-residuos-e-economia-circular', 'Resíduos e economia circular', 'Avalie prevenção, reutilização, reparo, reciclagem e destinação adequada. Diferencie geração evitada de desvio de aterro e evite dupla contagem. Indicadores possíveis: kg gerados; kg reciclados; taxa de desvio %.', 'evaluation_criteria', 'Ambiental (E)', 'GRI Standards — referência temática geral; verificar norma temática e edição aplicável antes de declarar alinhamento.'),
  ('esg-12-emissoes-de-gases-de-efeito-estufa', 'Emissões de gases de efeito estufa', 'Identifique ações que podem reduzir emissões e peça escopo, fatores de emissão, linha de base e método. Não calcule tCO₂e sem dados e premissas explícitos. Indicadores possíveis: tCO₂e; tCO₂e/unidade.', 'evaluation_criteria', 'Ambiental (E)', 'GRI Standards — referência temática geral; verificar norma temática e edição aplicável antes de declarar alinhamento.'),
  ('esg-13-biodiversidade-e-uso-do-solo', 'Biodiversidade e uso do solo', 'Avalie proteção de habitats, recuperação de áreas e prevenção de danos. Solicite localização, área, espécies/ambientes afetados e monitoramento. Indicadores possíveis: ha restaurados; áreas monitoradas.', 'evaluation_criteria', 'Ambiental (E)', 'GRI Standards — referência temática geral; verificar norma temática e edição aplicável antes de declarar alinhamento.'),
  ('esg-14-poluicao-e-materiais-perigosos', 'Poluição e materiais perigosos', 'Reconheça redução de ruído, particulados, químicos e riscos de contaminação. Exija análise técnica e regulatória quando houver substâncias perigosas. Indicadores possíveis: concentração de poluentes; incidentes.', 'evaluation_criteria', 'Ambiental (E)', 'GRI Standards — referência temática geral; verificar norma temática e edição aplicável antes de declarar alinhamento.'),
  ('esg-15-saude-e-seguranca-ocupacional', 'Saúde e segurança ocupacional', 'Reconheça prevenção de acidentes e doenças, ergonomia, controles de risco e capacitação. Peça perigos, população exposta, controles existentes e avaliação especializada quando necessária.', 'evaluation_criteria', 'Social (S)', 'GRI Standards — referência temática geral; verificar norma temática e edição aplicável antes de declarar alinhamento.'),
  ('esg-16-capacitacao-e-desenvolvimento', 'Capacitação e desenvolvimento', 'Avalie aprendizagem, qualificação e empregabilidade. Diferencie número de participantes de melhoria de competência; solicite avaliação antes/depois.', 'evaluation_criteria', 'Social (S)', 'GRI Standards — referência temática geral; verificar norma temática e edição aplicável antes de declarar alinhamento.'),
  ('esg-17-diversidade-equidade-e-inclusao', 'Diversidade, equidade e inclusão', 'Reconheça redução de barreiras e ampliação de acesso e oportunidades. Evite inferir atributos pessoais e não solicite dados sensíveis desnecessários.', 'evaluation_criteria', 'Social (S)', 'GRI Standards — referência temática geral; verificar norma temática e edição aplicável antes de declarar alinhamento.'),
  ('esg-18-direitos-humanos-e-condicoes-de-trabalho', 'Direitos humanos e condições de trabalho', 'Avalie respeito a direitos, condições dignas e mecanismos de proteção. Sinalize situações graves para revisão humana, sem conclusões automáticas.', 'evaluation_criteria', 'Social (S)', 'GRI Standards — referência temática geral; verificar norma temática e edição aplicável antes de declarar alinhamento.'),
  ('esg-19-bem-estar-e-saude-mental', 'Bem-estar e saúde mental', 'Reconheça ações sobre condições de trabalho, apoio e prevenção. Não trate relatos individuais de saúde como evidência pública; use dados agregados e consentimento quando aplicável.', 'evaluation_criteria', 'Social (S)', 'GRI Standards — referência temática geral; verificar norma temática e edição aplicável antes de declarar alinhamento.'),
  ('esg-20-relacionamento-com-comunidades', 'Relacionamento com comunidades', 'Identifique benefícios e possíveis impactos sobre comunidades. Solicite definição de beneficiários, participação, contrapartidas e avaliação de efeitos adversos.', 'evaluation_criteria', 'Social (S)', 'GRI Standards — referência temática geral; verificar norma temática e edição aplicável antes de declarar alinhamento.'),
  ('esg-21-acessibilidade-e-inclusao-digital', 'Acessibilidade e inclusão digital', 'Avalie redução de barreiras físicas, digitais e comunicacionais. Solicite testes com usuários, requisitos de acessibilidade e evidências de uso efetivo.', 'evaluation_criteria', 'Social (S)', 'GRI Standards — referência temática geral; verificar norma temática e edição aplicável antes de declarar alinhamento.'),
  ('esg-22-etica-e-integridade', 'Ética e integridade', 'Reconheça medidas de prevenção de condutas impróprias, orientação e responsabilização. Não equipare treinamento isolado à eficácia do programa.', 'evaluation_criteria', 'Governança (G)', 'GRI Standards — referência temática geral; verificar norma temática e edição aplicável antes de declarar alinhamento.'),
  ('esg-23-prevencao-de-corrupcao-e-conflitos-de-interesse', 'Prevenção de corrupção e conflitos de interesse', 'Avalie controles sobre presentes, fornecedores, decisões e conflitos. Encaminhe indícios concretos de irregularidade para canal apropriado e revisão humana.', 'evaluation_criteria', 'Governança (G)', 'GRI Standards — referência temática geral; verificar norma temática e edição aplicável antes de declarar alinhamento.'),
  ('esg-24-conformidade-legal-e-normativa', 'Conformidade legal e normativa', 'Verifique se a proposta identifica obrigações aplicáveis e responsáveis. A IA não deve declarar conformidade jurídica sem validação especializada.', 'evaluation_criteria', 'Governança (G)', 'GRI Standards — referência temática geral; verificar norma temática e edição aplicável antes de declarar alinhamento.'),
  ('esg-25-gestao-de-riscos-e-controles', 'Gestão de riscos e controles', 'Avalie identificação de riscos, probabilidade, impacto, mitigação, responsáveis e evidências de funcionamento dos controles.', 'evaluation_criteria', 'Governança (G)', 'GRI Standards — referência temática geral; verificar norma temática e edição aplicável antes de declarar alinhamento.'),
  ('esg-26-transparencia-e-prestacao-de-contas', 'Transparência e prestação de contas', 'Reconheça divulgação clara, verificável e tempestiva de decisões e resultados. Solicite fonte, período, metodologia e limitações.', 'evaluation_criteria', 'Governança (G)', 'GRI Standards — referência temática geral; verificar norma temática e edição aplicável antes de declarar alinhamento.'),
  ('esg-27-protecao-de-dados-e-privacidade', 'Proteção de dados e privacidade', 'Avalie minimização de dados, finalidade, acesso, retenção e segurança. Não inclua dados pessoais de funcionários na base de conhecimento.', 'evaluation_criteria', 'Governança (G)', 'GRI Standards — referência temática geral; verificar norma temática e edição aplicável antes de declarar alinhamento.'),
  ('esg-28-compras-responsaveis-e-cadeia-de-fornecedores', 'Compras responsáveis e cadeia de fornecedores', 'Avalie critérios socioambientais em compras, diligência de fornecedores e monitoramento. Não presuma conformidade de terceiros sem evidências.', 'evaluation_criteria', 'Governança (G)', 'GRI Standards — referência temática geral; verificar norma temática e edição aplicável antes de declarar alinhamento.'),
  ('esg-29-triagem-semantica-contextual', 'Triagem semântica contextual', 'Interprete objetivo, ação proposta, público afetado e resultado esperado; palavras-chave são sinais auxiliares, nunca prova de impacto.', 'classification_rule', 'Avaliação e triagem', 'Referência metodológica interna proposta — Copiloto ESG v1.0 (não é norma externa).'),
  ('esg-30-pontuacao-ponderada-de-propostas', 'Pontuação ponderada de propostas', 'Atribua notas 0–5 a impacto ESG (25%), viabilidade técnica (15%), econômica (10%), inovação (10%), alinhamento estratégico (15%), mensurabilidade (10%), escalabilidade (5%) e maturidade (10%). Calcule soma de nota/5 × peso.', 'classification_rule', 'Avaliação e triagem', 'Referência metodológica interna proposta — Copiloto ESG v1.0 (não é norma externa).'),
  ('esg-31-faixas-de-potencial', 'Faixas de potencial', 'Classifique 0–19 muito baixo, 20–39 baixo, 40–59 moderado, 60–79 alto e 80–100 muito alto. A faixa não significa aprovação nem conformidade.', 'classification_rule', 'Avaliação e triagem', 'Referência metodológica interna proposta — Copiloto ESG v1.0 (não é norma externa).'),
  ('esg-32-confianca-da-ia-e-insuficiencia-de-dados', 'Confiança da IA e insuficiência de dados', 'Apresente confiança separada da nota de potencial. Se faltarem evidências ou detalhes, marque incertezas, solicite informações e não fabrique números.', 'classification_rule', 'Avaliação e triagem', 'Referência metodológica interna proposta — Copiloto ESG v1.0 (não é norma externa).'),
  ('esg-33-viabilidade-tecnica-e-economica', 'Viabilidade técnica e econômica', 'Analise recursos, tecnologia, segurança, prazo, custo e dependências; ausência de orçamento não implica custo zero. Encaminhe decisões relevantes para especialistas.', 'classification_rule', 'Avaliação e triagem', 'Referência metodológica interna proposta — Copiloto ESG v1.0 (não é norma externa).'),
  ('esg-34-riscos-excecoes-e-revisao-humana', 'Riscos, exceções e revisão humana', 'Propostas com riscos legais, ambientais, segurança ou privacidade devem passar por revisão humana. Não permita aprovação automática baseada apenas no score.', 'classification_rule', 'Avaliação e triagem', 'Referência metodológica interna proposta — Copiloto ESG v1.0 (não é norma externa).'),
  ('esg-35-deteccao-de-duplicidade', 'Detecção de duplicidade', 'Compare propósito, solução, local, beneficiários e resultados com propostas anteriores; sinalize similaridade e ofereça consolidação, sem descartar automaticamente.', 'classification_rule', 'Avaliação e triagem', 'Referência metodológica interna proposta — Copiloto ESG v1.0 (não é norma externa).'),
  ('esg-36-aprimoramento-pelo-copiloto', 'Aprimoramento pelo copiloto', 'Faça perguntas objetivas sobre problema, cenário atual, solução, público, recursos, métricas e riscos. Sugira melhorias sem alterar a intenção original do funcionário.', 'classification_rule', 'Avaliação e triagem', 'Referência metodológica interna proposta — Copiloto ESG v1.0 (não é norma externa).'),
  ('esg-37-indicadores-smart-e-mensurabilidade', 'Indicadores SMART e mensurabilidade', 'Recomende métricas específicas, mensuráveis, alcançáveis, relevantes e temporais. Defina unidade, período, linha de base, meta, responsável e fonte.', 'recommendation', 'Indicadores e evidências', 'Referência metodológica interna proposta — Copiloto ESG v1.0 (não é norma externa).'),
  ('esg-38-qualidade-das-evidencias', 'Qualidade das evidências', 'Diferencie declaração, estimativa, medição, documento e validação independente. Registre origem, data, método e limitações; não trate estimativa como resultado medido.', 'recommendation', 'Indicadores e evidências', 'Referência metodológica interna proposta — Copiloto ESG v1.0 (não é norma externa).'),
  ('esg-39-calculo-e-verificacao-de-beneficios', 'Cálculo e verificação de benefícios', 'Exija premissas explícitas, comparação consistente e controle de fatores externos. Mostre fórmula e unidades; evite dupla contagem e extrapolação injustificada.', 'recommendation', 'Indicadores e evidências', 'Referência metodológica interna proposta — Copiloto ESG v1.0 (não é norma externa).'),
  ('esg-40-prevencao-de-alegacoes-esg-sem-comprovacao', 'Prevenção de alegações ESG sem comprovação', 'Quando houver promessa ambiental/social sem evidência, marque como alegação a verificar. Solicite documentação; não rotule automaticamente a empresa como praticante de greenwashing.', 'recommendation', 'Indicadores e evidências', 'Referência metodológica interna proposta — Copiloto ESG v1.0 (não é norma externa).')
),
inserted as (
  insert into public.esg_knowledge_items (slug, title, description, category, thematic_category, source, status, origin)
  select s.slug, s.title, s.description, s.category, s.thematic_category, s.source, 'active', 'seed:base-esg-v1'
  from seed s
  where not exists (
    select 1 from public.esg_knowledge_items k
    where k.slug = s.slug or lower(k.title) = lower(s.title)
  )
  on conflict (slug) do nothing
  returning slug
)
select
  (select count(*) from seed) as registros_no_arquivo,
  (select count(*) from inserted) as inseridos_agora,
  (select count(*) from seed) - (select count(*) from inserted) as ja_existiam;

commit;
